{"file_path": "gateway-service/src/main/java/cn/com/cathayins/wireless/eclipse/assembler/ClientAssembler.java", "start_line": 1, "end_line": 112, "lines_total": 112, "truncated": false, "content": "package cn.com.cathayins.wireless.eclipse.assembler;

import cn.com.cathayins.externallogin.dto.*;
import cn.com.cathayins.wireless.eclipse.gateway.service.dto.PhoneLoginDTO;
import cn.com.cathayins.wireless.eclipse.gateway.service.dto.client.*;
import cn.com.cathayins.wireless.eclipse.gateway.service.dto.CertifyInfoDTO;
import org.springframework.stereotype.Component;


/**
 * @author wanghaotian
 * @create 2019/05/06 14:54
 * @desc client转换
 */
@Component
public class ClientAssembler {

    public IdentityInfoRequestDto from(CertifyInfoDTO certifyDTO){
        IdentityInfoRequestDto identityInfoRequestDto = new IdentityInfoRequestDto();
        identityInfoRequestDto.setCertificateNo(certifyDTO.getCertificateNo());
        identityInfoRequestDto.setName(certifyDTO.getName());
        identityInfoRequestDto.setCertificateTypeCd(certifyDTO.getCertificateType());
        return identityInfoRequestDto;
    }

    public PassportDTO from(TokenExPassportDto tokenExPassportDto) {
        if (tokenExPassportDto == null) {
            return null;
        }
        return new PassportDTO(
                tokenExPassportDto.getPassportId(),
                tokenExPassportDto.getUserId(),
                tokenExPassportDto.getAuthScene(),
                tokenExPassportDto.getDeviceType(),
                tokenExPassportDto.getAliasType(),
                tokenExPassportDto.getAliasValue(),
                tokenExPassportDto.getPassportRole());
    }
    /**
     * authorizationDTO to AliOauthSupplyInfoDto
     * @param authorizationDTO
     * @return
     */
    public AliOauthSupplyInfoDto from(AuthorizationDTO authorizationDTO) {
        if (authorizationDTO == null) {
            return null;
        }
        AliOauthSupplyInfoDto aliOauthSupplyInfoDto = new AliOauthSupplyInfoDto();
        aliOauthSupplyInfoDto.setAuthCode(authorizationDTO.getAuthCode());
        aliOauthSupplyInfoDto.setScope(authorizationDTO.getScope());
        aliOauthSupplyInfoDto.setAppIdName(authorizationDTO.getAppIdName());
        aliOauthSupplyInfoDto.setUserId(authorizationDTO.getUserId());

        return aliOauthSupplyInfoDto;
    }
    /**
     * oauthLoginDto to AliOauthLoginDto
     * @param oauthLoginDto
     * @return
     */
    public AliOauthLoginDto from(OauthLoginDTO oauthLoginDto) {
        if (oauthLoginDto == null) {
            return null;
        }
        AliOauthLoginDto aliOauthLoginDto = new AliOauthLoginDto();
        aliOauthLoginDto.setAuthCode(oauthLoginDto.getAuthCode());
        aliOauthLoginDto.setScope(oauthLoginDto.getScope());
        aliOauthLoginDto.setAppIdName(oauthLoginDto.getAppIdName());
        aliOauthLoginDto.setPassportRole(oauthLoginDto.getPassportRole());
        aliOauthLoginDto.setAuthScene(oauthLoginDto.getAuthScene());
        aliOauthLoginDto.setDeviceType(oauthLoginDto.getDeviceType());
        return aliOauthLoginDto;
    }


    /**
     * aliOauthLoginResultDto to TokenDTO
     * @param aliOauthLoginResultDto
     * @return
     */
    public TokenDTO from(CommonLoginResultDto aliOauthLoginResultDto) {
        if (aliOauthLoginResultDto == null) {
            return null;
        }
        return new TokenDTO(
                aliOauthLoginResultDto.getToken(),
                aliOauthLoginResultDto.getExpireAfterSeconds());
    }

    /**
     * convert phoneLoginDTO to PhoneLoginDto
     *
     * @param phoneLoginDTO
     * @return
     */
    public PhoneLoginDto toPhoneLoginDTO(PhoneLoginDTO phoneLoginDTO) {
        if (phoneLoginDTO == null) {
            return null;
        }

        PhoneLoginDto response = new PhoneLoginDto();
        response.setAuthScene(phoneLoginDTO.getAuthScene());
        response.setDeviceId(phoneLoginDTO.getDeviceId());
        response.setDeviceType(phoneLoginDTO.getDeviceType());
        response.setAuthScene(phoneLoginDTO.getAuthScene());
        response.setPhoneNo(phoneLoginDTO.getPhoneNo());

        return response;
    }


}
"}

