import static java.util.Objects.nonNull;
import static org.apache.commons.lang3.Validate.notBlank;
import static org.apache.commons.lang3.Validate.notNull;


/**
 * @author i01007600693
 * @Date: 2019/5/18 15:00
 * @Description: 用户信息
 */
@Slf4j
@Service
public class UserServiceImpl implements UserService {

    @Inject
    private ExternalClientService externalClientService;
    @Autowired
    private ExternalExternalLoginService externalExternalLoginService;
    @Autowired
    private ExternalUserContactService externalUserContactService;
    @Autowired
    private ShortMessageVerificationService shortMessageVerificationService;

    /**
     * 静默授权登录
     *
     * @param loginDTO 请求对象
     * @return TokenDTO
     */
    @Override
    public TokenDTO login(String channelSource, LoginDTO loginDTO) {
        if (loginDTO instanceof OauthLoginDTO) {
            OauthLoginDTO oauthLogin = (OauthLoginDTO) loginDTO;
            notNull(oauthLogin, "oauthLoginDTO is required!");
            notBlank(oauthLogin.getAuthCode(), "authCode is required!");
            notBlank(oauthLogin.getScope(), "scope is required!");
            notBlank(oauthLogin.getAppIdName(), "appIdName is required!");
            notBlank(oauthLogin.getAuthScene(), "authScene is required!");
            notNull(oauthLogin.getDeviceType(), "deviceType is required!");
            // 入参对象转换
            AliOauthLoginDto aliOauthLoginDto = new ClientAssembler().from(oauthLogin);
            // 调用客户域获取token和失效时间
            CommonLoginResultDto loginResult = externalClientService.oauthLogin(channelSource, aliOauthLoginDto);
            // 出参对象转换
            return new ClientAssembler().from(loginResult);
        }
        throw new BizException("登陆异常,非授权登陆实例");
    }

    /**
     * 支付宝授权补全信息
     *
     * @param authorizationDTO authorizationDTO
     * @return boolean
     */
    @Override
    public boolean supplyBaseInfo(AuthorizationDTO authorizationDTO) {

        notNull(authorizationDTO, "authorizationDTO is required!");
        notBlank(authorizationDTO.getAuthCode(), "authCode is required!");
        notBlank(authorizationDTO.getScope(), "scope is required!");
        notBlank(authorizationDTO.getAppIdName(), "appIdName is required!");
        notBlank(authorizationDTO.getUserId(), "userId is required!");

        AliOauthSupplyInfoDto aliOauthSupplyInfoDto = new ClientAssembler().from(authorizationDTO);

        return externalClientService.oauthSupplyInfo(aliOauthSupplyInfoDto);
    }

    /**
     * 用户信息包含userId，userIds，partyId，phoneNo，userName
     * 1.校验token有效性并刷新token时间
     * 2.查询用户userId
     * 3.查询用户证件信息
     * 4.查询用户证件关联的userId列表
     * 5.查询用户联系方式
     *
     * @param token
     * @return
     */
    @Override
    public UserDTO getUserInfo(String token) {
        if (refreshToken(token)) {
            UserDTO userDTO = new UserDTO();
            TokenExPassportDto tokenExPassportDto = externalExternalLoginService.tokenToUserInfo(token);
            userDTO.setUserId(tokenExPassportDto.getUserId());
            CertifyInfoDTO certifyInfoDTO = externalClientService.userCertifyInfo(userDTO.getUserId());
            if (certifyInfoDTO != null) {
                userDTO.setUserName(certifyInfoDTO.getName());
                userDTO.setPartyId(certifyInfoDTO.getPartyId());
                IdentityInfoRequestDto identityInfoRequestDto = new ClientAssembler().from(certifyInfoDTO);
                List<Long> userIds = externalClientService.userIds(identityInfoRequestDto);
                userDTO.setUserIds(longToString(userIds));
            }
            //0:用户名,1:手机号,2:邮箱,3:支付宝uid
            userDTO.setAccountNo(tokenExPassportDto.getAliasValue());

            ContactWayDTO contactWayDTO = externalUserContactService.queryDefaultMobileContact(Long.valueOf(tokenExPassportDto.getUserId()));
            if (contactWayDTO != null) {
                userDTO.setPhoneNo(contactWayDTO.getContactContent());
            }
            return userDTO;
        }
        throw new TokenException(GawErrorCodeEnum.LOGIN_EXPIRED);
    }

    private List<String> longToString(List<Long> longList) {
        List<String> stringList = Lists.newArrayList();
        longList.forEach(a -> stringList.add(String.valueOf(a)));
        return stringList;
    }


    /**
     * 登录令牌有效性检查
     * 1.校验token有效性
     * 2.若token有效则刷新token有效时间
     *
     * @param token token
     * @return Boolean
     */
    @Override
    public Boolean refreshToken(String token) {
        notBlank(token, "token is not Blank");
        return externalClientService.refreshToken(token);
    }

    /**
     * 绑定用户手机号
     * 1.校验验证码是否正确
     * 1）不正确抛出异常
     * 2.设置用户手机号
     *
