import cn.com.cathayins.wireless.eclipse.gateway.common.enums.GawErrorCodeEnum;
import cn.com.cathayins.wireless.eclipse.gateway.common.enums.ShortMessageTypeEnum;
import cn.com.cathayins.wireless.eclipse.gateway.common.exception.BizException;
import cn.com.cathayins.wireless.eclipse.gateway.common.exception.TokenException;
import cn.com.cathayins.wireless.eclipse.gateway.external.ExternalClientService;
import cn.com.cathayins.wireless.eclipse.gateway.external.ExternalExternalLoginService;
import cn.com.cathayins.wireless.eclipse.gateway.external.ExternalUserContactService;
import cn.com.cathayins.wireless.eclipse.gateway.service.dto.CertifyInfoDTO;
